#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-2.0-or-later
"""Generate the standalone RGB32 benchmark shaders using an offline glslc."""

import sys

sys.dont_write_bytecode = True

import argparse
from pathlib import Path
import struct
import subprocess
import tempfile


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--glslc", required=True, type=Path)
    parser.add_argument("--verify", action="store_true")
    options = parser.parse_args()
    directory = Path(__file__).resolve().parent / "shaders"
    output = ["// SPDX-License-Identifier: GPL-2.0-or-later",
              "// Generated by tests/perf/generate_rgb32_texel.py; do not edit.",
              "#pragma once", "#include <array>", "#include <cstdint>",
              "namespace rgb32_texel {", ""]
    with tempfile.TemporaryDirectory(prefix="rgb32-texel-") as temporary:
        for kind, name in enumerate(("floating", "signed_integer", "unsigned_integer")):
            binary = Path(temporary) / f"{name}.spv"
            subprocess.run([str(options.glslc.resolve()), "--target-env=vulkan1.1", "-O",
                            f"-DDATA_KIND={kind}", str(directory / "rgb32_texel.comp"),
                            "-o", str(binary)], check=True)
            payload = binary.read_bytes()
            words = struct.unpack(f"<{len(payload) // 4}I", payload)
            output.append(f"inline constexpr std::array<uint32_t, {len(words)}> {name}{{")
            for start in range(0, len(words), 6):
                output.append("    " + ", ".join(f"0x{word:08x}" for word in words[start:start + 6]) + ",")
            output.extend(["};", ""])
    output.extend(["} // namespace rgb32_texel", ""])
    text = "\n".join(output)
    destination = directory / "rgb32_texel_spirv.hpp"
    if options.verify:
        if destination.read_text() != text:
            raise SystemExit("RGB32 benchmark shader header is stale")
    else:
        destination.write_text(text)


if __name__ == "__main__":
    main()
